window.getBulkWorkMemoMaintenanceMachine_ = (draft) => {
  const id = String(draft && draft.maintenanceToolId || '').trim();
  if (!id) return null;
  if (typeof window.findMaintenanceTargetById_ === 'function') {
    return window.findMaintenanceTargetById_(id);
  }
  return (typeof pdlMachines !== 'undefined' && Array.isArray(pdlMachines))
    ? pdlMachines.find(m => m && String(m.id) === id) || null
    : null;
};

window.getBulkWorkMemoMaintenanceSymptomOptions_ = (draft) => {
  const machine = window.getBulkWorkMemoMaintenanceMachine_(draft);
  const cat = machine ? String(machine.category || machine.type || '').trim() : '';
  const set = new Set();
  if (machine && machine.symptoms) {
    String(machine.symptoms).split(/[,、]/).map(s => s.trim()).filter(Boolean).forEach(s => set.add(s));
  }
  if (cat && Array.isArray(pdlMachines)) {
    pdlMachines.filter(m => (m.category === cat || m.type === cat) && m.symptoms).forEach(m => {
      String(m.symptoms).split(/[,、]/).map(s => s.trim()).filter(Boolean).forEach(s => set.add(s));
    });
  }
  (window.pdlSymptoms || ['動作不良', '異音発生', '苗箱の詰まり', 'エンジン始動不能', 'オイル漏れ', 'ベルト緩み・破損', '刃・パーツ破損', 'ランプ点灯', '点検・清掃']).forEach(s => set.add(s));
  const cur = String(draft && draft.maintenanceSymptom || '').trim();
  if (cur && !set.has(cur)) set.add(cur);
  return Array.from(set);
};

window.getBulkWorkMemoMaintenanceContentOptions_ = (draft) => {
  const set = new Set(window.pdlMaintenanceContents || []);
  ['オイル交換', 'エレメント交換', 'ベルト調整', 'グリスアップ', '刃交換', '清掃・点検', '部品交換', '本体修理', '動作確認'].forEach(c => set.add(c));
  const cur = String(draft && draft.maintenanceContent || '').trim();
  if (cur && !set.has(cur)) set.add(cur);
  return Array.from(set);
};

window.getBulkWorkMemoMaintenancePartsOptions_ = (draft) => {
  const machine = window.getBulkWorkMemoMaintenanceMachine_(draft);
  const cat = machine ? String(machine.category || machine.type || '').trim() : '';
  const set = new Set();
  if (machine && machine.parts) {
    String(machine.parts).split(/[,、]/).map(p => p.trim()).filter(Boolean).forEach(p => set.add(p));
  }
  if (cat && Array.isArray(pdlMachines)) {
    pdlMachines.filter(m => (m.category === cat || m.type === cat) && m.parts).forEach(m => {
      String(m.parts).split(/[,、]/).map(p => p.trim()).filter(Boolean).forEach(p => set.add(p));
    });
  }
  (window.pdlMaintenanceParts || ['プラグ', 'オイルフィルター', 'エアフィルター', 'Vベルト', '替刃', 'ヒューズ', 'バッテリー', 'Oリング']).forEach(p => set.add(p));
  const cur = String(draft && draft.maintenanceParts || '').trim();
  if (cur && !set.has(cur)) set.add(cur);
  return Array.from(set);
};

window.guessBulkWorkMemoMaintenanceFields_ = (draft) => {
  const t = String(draft && draft.rawLine || '');
  if (!t) return;
  const pickFromList = (list, key) => {
    if (String(draft[key] || '').trim()) return;
    for (let i = 0; i < list.length; i++) {
      const item = String(list[i] || '').trim();
      if (item.length >= 2 && t.indexOf(item) >= 0) {
        draft[key] = item;
        return;
      }
    }
  };
  pickFromList(window.getBulkWorkMemoMaintenanceSymptomOptions_(draft), 'maintenanceSymptom');
  pickFromList(window.getBulkWorkMemoMaintenanceContentOptions_(draft), 'maintenanceContent');
  pickFromList(window.getBulkWorkMemoMaintenancePartsOptions_(draft), 'maintenanceParts');
  if (!String(draft.maintenanceContent || '').trim()) {
    if (/修理/.test(t)) draft.maintenanceContent = '本体修理';
    else if (/点検|清掃/.test(t)) draft.maintenanceContent = '清掃・点検';
    else if (/オイル/.test(t)) draft.maintenanceContent = 'オイル交換';
  }
};

window.buildBulkWorkMemoMaintenanceFieldChipsHtml_ = (uid, field, label, options, cur, tone) => {
  const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
  const selected = String(cur || '').trim();
  const colors = {
    orange: { on: '#E65100', off: '#FFF3E0', border: '#FFB74D', offBorder: '#FFE0B2' },
    green: { on: '#2E7D32', off: '#E8F5E9', border: '#66BB6A', offBorder: '#C8E6C9' },
    blue: { on: '#1565C0', off: '#E3F2FD', border: '#64B5F6', offBorder: '#BBDEFB' }
  };
  const c = colors[tone] || colors.orange;
  const chips = (options || []).slice(0, 16).map(val => {
    const on = val === selected;
    const safe = String(val).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
    const safeField = String(field).replace(/'/g, "\\'");
    return `<button type="button" onclick="pickBulkWorkMemoMaintenanceField_('${esc(uid)}','${safeField}','${safe}')" style="padding:6px 10px; border-radius:14px; font-size:12px; font-weight:bold; cursor:pointer; border:2px solid ${on ? c.on : c.offBorder}; background:${on ? c.on : c.off}; color:${on ? '#fff' : c.on};">${esc(val)}</button>`;
  }).join('');
  const inputId = `bulk_maint_${field}_${esc(uid)}`;
  const placeholders = {
    maintenanceSymptom: 'その他の症状を直接入力',
    maintenanceContent: 'その他の整備内容を直接入力',
    maintenanceParts: 'その他の部品名を直接入力'
  };
  return `<div style="margin-top:10px;">
    <div style="font-size:10px; font-weight:bold; color:${c.on}; margin-bottom:6px;">${label}</div>
    <div style="display:flex; flex-wrap:wrap; gap:6px; margin-bottom:6px;">${chips || `<span style="font-size:11px; color:#888;">候補がありません。下に直接入力してください。</span>`}</div>
    <input type="text" id="${inputId}" value="${esc(selected)}" placeholder="${esc(placeholders[field] || '')}" onchange="updateBulkWorkMemoMaintenanceCustom_('${esc(uid)}','${String(field).replace(/'/g, "\\'")}', this.value)" style="width:100%; box-sizing:border-box; padding:7px 10px; border:1px solid ${c.offBorder}; border-radius:8px; font-size:12px;">
  </div>`;
};

window.buildBulkWorkMemoMaintenanceTargetHtml_ = (d, uid) => {
  const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
  const curId = String(d.maintenanceToolId || '').trim();
  const kindFilter = String(d._maintKindFilter || 'all');
  const allTargets = window.getBulkWorkMemoMaintenanceTargets_(d);
  const targets = allTargets.filter(item => {
    if (kindFilter === 'all') return true;
    if (kindFilter === 'machine') return item.kind === 'machine';
    if (kindFilter === 'vehicle') return item.kind === 'vehicle';
    if (kindFilter === 'tool') return item.kind === 'tool';
    return true;
  });
  const kindBtn = (kind, icon, label) => {
    const on = kindFilter === kind;
    const safeKind = String(kind).replace(/'/g, "\\'");
    return `<button type="button" onclick="pickBulkWorkMemoMaintKindFilter_('${esc(uid)}','${safeKind}')" style="flex:1; min-width:72px; padding:8px 6px; border-radius:10px; font-size:12px; font-weight:bold; cursor:pointer; border:2px solid ${on ? '#E65100' : '#FFE0B2'}; background:${on ? '#FFF3E0' : '#fff'}; color:${on ? '#E65100' : '#666'};">${icon}${label}</button>`;
  };
  const kindFilterHtml = `<div style="display:flex; gap:6px; flex-wrap:wrap; margin-bottom:8px;">
    ${kindBtn('all', '', 'すべて')}
    ${kindBtn('machine', '🚜 ', '機械')}
    ${kindBtn('vehicle', '🛻 ', '車両')}
    ${kindBtn('tool', '🔧 ', '道具')}
  </div>`;
  const fmtLabel = (item, plain) => {
    if (typeof window.formatBulkMaintTargetChipHtml_ === 'function') {
      return window.formatBulkMaintTargetChipHtml_(item, !!plain);
    }
    if (typeof window.formatMachineOptionLabel === 'function') {
      return window.formatMachineOptionLabel(Object.assign({}, item, {
        isTool: item.kind === 'tool',
        isVehicle: item.kind === 'vehicle'
      }));
    }
    const icon = item.kind === 'vehicle' ? '🛻' : (item.kind === 'tool' ? '🔧' : '🚜');
    return icon + ' ' + item.name;
  };
  const chip = (item, style) => {
    const on = String(item.id) === curId;
    const safeId = String(item.id).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
    const safeName = String(item.name).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
    const safeKind = String(item.kind || 'machine').replace(/'/g, "\\'");
    const searchHay = (typeof window.formatBulkMaintTargetSearchHay_ === 'function')
      ? window.formatBulkMaintTargetSearchHay_(item)
      : String(item.name || '').toLowerCase();
    const bg = on ? '#E65100' : (style === 'maybe' ? '#F3E5F5' : (style === 'sug' ? '#FFF8E1' : '#fff'));
    const border = on ? '#BF360C' : (style === 'maybe' ? '#CE93D8' : (style === 'sug' ? '#FFB74D' : '#FFE0B2'));
    const inner = (typeof window.buildBulkMaintTargetChipInnerHtml_ === 'function')
      ? window.buildBulkMaintTargetChipInnerHtml_(item, on)
      : esc(String(item.name || ''));
    return `<button type="button" class="bulk-maint-target-chip" data-name="${esc(item.name)}" data-search="${esc(searchHay)}" data-kind="${esc(item.kind || 'machine')}" onclick="pickBulkWorkMemoMaintenanceTarget_('${esc(uid)}','${safeId}','${safeName}','${safeKind}')" style="display:flex; flex-direction:column; align-items:stretch; width:100%; padding:0; border-radius:10px; overflow:hidden; border:2px solid ${border}; background:${bg}; cursor:pointer; text-align:left; line-height:1.3; min-height:0; box-shadow:${on ? '0 2px 8px rgba(191,54,12,0.25)' : 'none'};">${inner}</button>`;
  };
  const suggestedSet = new Set();
  const sug = window.suggestBulkWorkMemoMaintenanceTargets_(d.rawLine);
  (sug.primary || []).forEach(item => suggestedSet.add(String(item.id)));
  (sug.maybe || []).forEach(item => suggestedSet.add(String(item.id)));
  const primarySug = (sug.primary || []).filter(item => {
    if (kindFilter === 'all') return true;
    if (kindFilter === 'machine') return item.kind === 'machine';
    if (kindFilter === 'vehicle') return item.kind === 'vehicle';
    if (kindFilter === 'tool') return item.kind === 'tool';
    return true;
  });
  const maybeSug = (sug.maybe || []).filter(item => {
    if (kindFilter === 'all') return true;
    if (kindFilter === 'machine') return item.kind === 'machine';
    if (kindFilter === 'vehicle') return item.kind === 'vehicle';
    if (kindFilter === 'tool') return item.kind === 'tool';
    return true;
  }).filter(item => !primarySug.some(p => String(p.id) === String(item.id)));
  const sugHtml = primarySug.length
    ? `<div style="font-size:10px; color:#E65100; font-weight:bold; margin:6px 0 4px;">メモから合いそうな機械・道具</div>
       <div style="display:grid; grid-template-columns:repeat(auto-fill, minmax(128px, 1fr)); gap:8px; margin-bottom:8px;">${primarySug.map(item => chip(item, 'sug')).join('')}</div>`
    : '';
  const maybeHtml = maybeSug.length
    ? `<div style="font-size:10px; color:#7B1FA2; font-weight:bold; margin:0 0 4px;">もしかして：</div>
       <div style="display:grid; grid-template-columns:repeat(auto-fill, minmax(128px, 1fr)); gap:8px; margin-bottom:10px;">${maybeSug.map(item => chip(item, 'maybe')).join('')}</div>`
    : '';
  const listTargets = targets.filter(item => !suggestedSet.has(String(item.id)));
  const listHtml = listTargets.length
    ? `<div style="font-size:10px; color:#888; font-weight:bold; margin:0 0 6px;">一覧から選ぶ</div>
       <div style="display:grid; grid-template-columns:repeat(auto-fill, minmax(128px, 1fr)); gap:8px; max-height:280px; overflow-y:auto; padding:2px;">${listTargets.slice(0, 48).map(item => chip(item, 'all')).join('')}</div>`
    : (!primarySug.length && !maybeSug.length
      ? `<div style="font-size:11px; color:#888; padding:8px;">${kindFilter !== 'all' ? 'この種類の' : ''}機械・道具・車両がありません。</div>`
      : '');
  const selectedTarget = curId ? allTargets.find(t => String(t.id) === curId) : null;
  const fmtPlain = (item) => {
    if (!item) return String(d.maintenanceTool || '').trim();
    if (typeof window.formatBulkMaintTargetChipHtml_ === 'function') {
      const plain = window.formatBulkMaintTargetChipHtml_(item, true);
      return plain.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
    }
    return String(item.name || d.maintenanceTool || '').trim();
  };
  const collapsed = curId && d._maintPickOpen !== true;
  const detailsHtml = `
    ${window.buildBulkWorkMemoMaintenanceFieldChipsHtml_(uid, 'maintenanceSymptom', '症状', window.getBulkWorkMemoMaintenanceSymptomOptions_(d), d.maintenanceSymptom, 'orange')}
    ${window.buildBulkWorkMemoMaintenanceFieldChipsHtml_(uid, 'maintenanceContent', '整備内容', window.getBulkWorkMemoMaintenanceContentOptions_(d), d.maintenanceContent, 'green')}
    ${window.buildBulkWorkMemoMaintenanceFieldChipsHtml_(uid, 'maintenanceParts', '交換部品名', window.getBulkWorkMemoMaintenancePartsOptions_(d), d.maintenanceParts, 'blue')}`;
  if (collapsed) {
    return `<div class="bulk-maint-target-box" style="margin:8px 0; background:#FFF3E0; border:2px solid #FFB74D; border-radius:10px; padding:10px;">
      ${window.buildBulkWorkMemoCollapsedPickHtml_({
        icon: '🔧',
        label: '整備・修理・点検',
        value: fmtPlain(selectedTarget),
        uid: uid,
        toggleFn: 'toggleBulkWorkMemoMaintPick_',
        borderColor: '#FFB74D',
        bgColor: '#FFF8E1',
        textColor: '#E65100'
      })}
      <div style="margin-top:10px; padding-top:10px; border-top:1px dashed #FFCC80;">${detailsHtml}</div>
    </div>`;
  }
  const badge = curId
    ? (typeof window.buildBulkMaintTargetSelectedBadgeHtml_ === 'function'
      ? window.buildBulkMaintTargetSelectedBadgeHtml_(selectedTarget, d.maintenanceTool, d.maintenanceTargetKind || 'machine')
      : `<div style="margin-bottom:8px; font-size:12px; color:#E65100; font-weight:bold; background:#FFE0B2; padding:6px 10px; border-radius:6px; line-height:1.35;">整備対象: <b>${fmtLabel(selectedTarget || { name: d.maintenanceTool, kind: d.maintenanceTargetKind || 'machine' }, true)}</b></div>`)
    : `<div style="margin-bottom:8px; font-size:11px; color:#666; background:#fff; padding:8px; border-radius:6px;">修理・点検した機械・道具・車両を選んでください（圃場か機械のどちらかは必須）</div>`;
  return `<div class="bulk-maint-target-box" data-bulk-uid="${esc(uid)}" style="margin:8px 0; background:#FFF3E0; border:2px solid #FFB74D; border-radius:10px; padding:10px;">
    <div style="font-size:11px; font-weight:bold; color:#E65100; margin-bottom:6px;">🔧 整備・修理・点検</div>
    ${badge}
    ${kindFilterHtml}
    ${sugHtml}
    ${maybeHtml}
    <input type="search" placeholder="名前・機械番号・ナンバー・型式で絞り込み…" oninput="filterBulkWorkMemoMaintTargetChips_(this)" style="width:100%; box-sizing:border-box; padding:7px 10px; border:1px solid #FFB74D; border-radius:8px; font-size:12px; margin-bottom:8px;">
    <div class="bulk-maint-fuzzy-row" style="display:none; margin-bottom:8px;"></div>
    ${listHtml}
    <div style="margin-top:10px; padding-top:10px; border-top:1px dashed #FFCC80;">${detailsHtml}</div>
  </div>`;
};

