window.buildBulkWorkMemoMaintenanceMasterSideEffects_ = (d, queued) => {
  const fx = [];
  if (!window.bulkWorkMemoIsMaintenance_(d)) return fx;
  const q = queued || { symptoms: new Set(), contents: new Set(), parts: new Set() };
  const toolId = String(d.maintenanceToolId || '').trim();
  const toolKind = String(d.maintenanceTargetKind || '').trim();
  const isMachine = toolId && toolKind === 'machine';
  const machine = isMachine ? window.getBulkWorkMemoMaintenanceMachine_(d) : null;

  const symptom = String(d.maintenanceSymptom || '').trim();
  if (symptom && !q.symptoms.has(symptom)) {
    const known = window.getBulkWorkMemoMaintenanceSymptomOptions_(Object.assign({}, d, { maintenanceSymptom: '' }));
    if (!known.includes(symptom)) {
      q.symptoms.add(symptom);
      if (isMachine && machine) {
        fx.push({ action: 'addMachineSymptom', params: { machineId: toolId, newSymptom: symptom } });
        const currentSymp = machine.symptoms ? machine.symptoms.split(/[,、]/).map(s => s.trim()) : [];
        if (!currentSymp.includes(symptom)) {
          machine.symptoms = machine.symptoms ? machine.symptoms + ',' + symptom : symptom;
        }
      }
      if (Array.isArray(window.pdlSymptoms) && !window.pdlSymptoms.includes(symptom)) {
        window.pdlSymptoms.push(symptom);
      } else if (!Array.isArray(window.pdlSymptoms)) {
        window.pdlSymptoms = [symptom];
      }
    }
  }

  const content = String(d.maintenanceContent || '').trim();
  if (content && !q.contents.has(content)) {
    const known = window.getBulkWorkMemoMaintenanceContentOptions_(Object.assign({}, d, { maintenanceContent: '' }));
    if (!known.includes(content)) {
      q.contents.add(content);
      fx.push({
        action: 'addMaintenanceContent',
        params: { name: content, userName: (typeof currentUser !== 'undefined' ? currentUser : '') }
      });
      if (!Array.isArray(window.pdlMaintenanceContents)) window.pdlMaintenanceContents = [];
      if (!window.pdlMaintenanceContents.includes(content)) window.pdlMaintenanceContents.push(content);
    }
  }

  const parts = String(d.maintenanceParts || '').trim();
  if (parts && isMachine && machine && !q.parts.has(parts)) {
    const known = window.getBulkWorkMemoMaintenancePartsOptions_(Object.assign({}, d, { maintenanceParts: '' }));
    if (!known.includes(parts)) {
      q.parts.add(parts);
      fx.push({ action: 'addMachinePart', params: { machineId: toolId, newPart: parts } });
      const currentParts = machine.parts ? machine.parts.split(/[,、]/).map(p => p.trim()) : [];
      if (!currentParts.includes(parts)) {
        machine.parts = machine.parts ? machine.parts + ',' + parts : parts;
      }
    }
  }
  return fx;
};

window.toggleBulkWorkMemoWorkList_ = (uid) => {
  const row = (window._bulkWorkMemoDrafts || []).find(d => d && d._uid === uid);
  if (!row) return;
  row._workListOpen = !row._workListOpen;
  if (row._workListOpen) {
    if (typeof window.refreshBulkWorkMemoWorkSuggestions_ === 'function') {
      window.refreshBulkWorkMemoWorkSuggestions_(row);
    }
  }
  window.renderBulkWorkMemoReviewModal_({ scrollUid: uid });
};

/** メモから作業名候補を再推定（手動検索を開く前など） */
window.refreshBulkWorkMemoWorkSuggestions_ = (d) => {
  if (!d || window.bulkWorkMemoIsRestDraft_(d) || String(d.workName || '').trim()) return;
  const scored = new Map();
  const addList = (list) => {
    (list || []).forEach(x => {
      const n = String(x && x.name || '').trim();
      if (!n || window.isBulkWorkMemoRestWorkName_(n)) return;
      const prev = scored.get(n);
      if (!prev || x.score > prev.score) scored.set(n, x);
    });
  };
  const raw = String(d._workMatchText || d.rawLine || '').trim();
  addList(window.suggestBulkWorkMemoWorkNames_(raw, d.startTime));
  const guessed = String(d.guessedName || '').trim();
  if (guessed && guessed !== raw) addList(window.suggestBulkWorkMemoWorkNames_(guessed, d.startTime));
  const sorted = Array.from(scored.values()).sort((a, b) => b.score - a.score);
  const split = window.splitBulkWorkMemoWorkSuggestions_(sorted);
  d.workCandidates = split.primary.map(x => x.name).filter(Boolean).slice(0, 8);
  d.workMaybeCandidates = split.maybe.map(x => x.name).filter(Boolean).slice(0, 4);
  d.workAliasHints = typeof window.buildBulkWorkMemoAliasHintsFromScored_ === 'function'
    ? window.buildBulkWorkMemoAliasHintsFromScored_(sorted)
    : {};
  if (!d.guessedName && sorted[0] && sorted[0].name) d.guessedName = sorted[0].name;
  if (sorted[0] && sorted[0].matchedAlias) d.guessedAlias = sorted[0].matchedAlias;
};

window.getBulkWorkMemoManualWorkList_ = (d) => {
  const filterCat = String(d && d.listFilterCategory != null ? d.listFilterCategory : '').trim();
  const metaAll = typeof window.isMetaTargetCategory_ === 'function' && window.isMetaTargetCategory_(filterCat);
  let names = (window.getBulkWorkMemoAllWorkNames_(filterCat) || []).filter(n => !window.isBulkWorkMemoRestWorkName_(n));
  let fallbackNote = '';
  if (!names.length && filterCat) {
    names = (window.getBulkWorkMemoAllWorkNames_('') || []).filter(n => !window.isBulkWorkMemoRestWorkName_(n));
    fallbackNote = `「${filterCat}」に該当する作業がないため、すべての作業を表示しています。`;
  }
  if (!names.length) {
    fallbackNote = '作業マスタが空です。「＋ マスタにない作業を登録」から追加できます。';
  }
  return { names, fallbackNote, filterCat };
};

window.refreshBulkWorkMemoAfterMachineChange_ = (machineRec) => {
  const uid = String(window._bulkWorkMemoMachineEditUid || '').trim();
  window._bulkWorkMemoMachineEditUid = '';
  if (!document.getElementById('bulk_work_memo_review_scroll')) return;
  const rec = machineRec && typeof machineRec === 'object' ? machineRec : {};
  const mid = String(rec.id || '').trim();
  const mname = String(rec.name || rec.plateNumber || '').trim();
  if (uid && (mid || mname)) {
    const row = (window._bulkWorkMemoDrafts || []).find(d => d && d._uid === uid);
    if (row) {
      if (!Array.isArray(row.usedMachines)) row.usedMachines = [];
      const exists = row.usedMachines.some(m =>
        (mid && String(m.id || '') === mid) || (mname && String(m.name || '') === mname)
      );
      if (!exists) row.usedMachines.push({ id: mid || mname, name: mname || mid });
      row._machinePickOpen = true;
    }
  }
  window.renderBulkWorkMemoReviewModal_({ scrollUid: uid });
};

