  const row = (window._bulkWorkMemoDrafts || []).find(d => d && d._uid === uid);
  if (!row) return;
  if (!window.bulkWorkMemoIsRestDraft_(row)) {
    window.renderBulkWorkMemoDraftEditor_(uid);
    return;
  }
  window.resetBulkWorkMemoDraftForWork_(row);
