            btn.style.cssText = 'background:#2E7D32; color:#fff; border:none; padding:8px 10px; border-radius:6px; font-weight:bold; cursor:pointer; flex-shrink:0; font-size:12px;';
            const closeBtn = headerRow.querySelector('button');
